import React from 'react';

import Footer from '../Common/Footer';
import NavBar from '../Common/NavBar';
import TopAdspaces_1 from '../Adspaces/TopAdspaces_1';
import TopAdspaces_2 from '../Adspaces/TopAdspaces_2';
import TopAdspaces_3 from '../Adspaces/TopAdspaces_3';



// functional component 
export default function Dashboard() {
  return (
    <body classNameName="hold-transition sidebar-mini layout-navbar-fixed">
      <div className="wrapper">
        <nav className="main-header navbar navbar-expand navbar-white navbar-light">
          <ul className="navbar-nav">
            <li className="nav-item">
              <a className="nav-link" data-widget="pushmenu" href="#" role="button"><i
                className="fas fa-bars"></i></a>
            </li>
          </ul>
          <ul className="navbar-nav ml-auto">
            <form action="" method="post">

              <input type="submit" value="Logout" className="btn btn-sm  mt-3" />
            </form>
          </ul>
        </nav>
        <aside class="main-sidebar sidebar-dark-primary elevation-4">
        </aside>
      </div>
    </body>
  )
}
